const LINE = 10
const CHIP_ON = { borderColor: 'var(--accent)', color: '#f4f4f6' }
const CHIP_OFF = { borderColor: 'rgba(255,255,255,0.1)', color: '#8b8b9a' }
const SEG_ON = { backgroundColor: 'rgba(255,255,255,0.12)', color: '#f4f4f6' }
const SEG_OFF = { backgroundColor: 'rgba(255,255,255,0)', color: '#8b8b9a' }

const build: Build = ({ tl, q, qa, step, final, move, click, type, wait, cursorOut }) => {
  const swap = (from: string, to: string, at: number | string = '<') => {
    tl.to(q(from), { opacity: 0, duration: 0.15 }, at)
    tl.to(q(to), { opacity: 1, duration: 0.2 }, '<0.05')
  }

  step(0)
  move('picker', { at: 0.4 })
  click('picker')
  tl.fromTo(
    q('popover'),
    { opacity: 0, y: -4 },
    { opacity: 1, y: 0, duration: 0.2, immediateRender: false },
    '<',
  )
  move('gen-button', { at: '+=0.5' })
  click('gen-button')
  tl.set(q('gen-ui'), { ...CHIP_OFF }, '<')
  tl.set(q('gen-button'), { ...CHIP_ON }, '<')
  tl.to(q('popover'), { opacity: 0, y: -4, duration: 0.15 }, '+=0.15')
  swap('name-ui', 'name-btn')
  swap('chips-ui', 'chips-btn', '<')
  swap('editor-ui', 'editor-btn', '<')
  swap('preview-ui', 'preview-btn', '<')
  swap('live', 'stages', '<')
  swap('code-0', 'code-1', '<')
  wait(0.5)

  step(1, '+=0.1')
  move('btn-glow', { at: '+=0.1' })
  tl.to(
    q('btn-glow'),
    { y: -1, boxShadow: PREVIEW.glowHover.boxShadow, duration: 0.25, ease: 'power2.out' },
    '>',
  )
  move('chip-1', { at: '+=0.6' })
  tl.to(q('btn-glow'), { y: 0, boxShadow: PREVIEW.glow.boxShadow, duration: 0.25 }, '<')
  click('chip-1')
  tl.set(q('chip-0'), { ...CHIP_OFF }, '<')
  tl.set(q('chip-1'), { ...CHIP_ON }, '<')
  swap('btn-glow', 'btn-shimmer')
  swap('code-1', 'code-2', '<')
  const shimmerAt = tl.duration()
  tl.to(q('code-2'), { y: -SHEEN_LINE * LINE + LINE, duration: 0.8, ease: 'power2.inOut' }, '+=0.4')
  wait(0.6)

  step(2, '+=0.1')
  move('class-input')
  click('class-input')
  tl.set(q('class-text'), { text: '' }, '>')
  type('class-text', CLASS_NAME, { at: '>', speed: 0.09 })
  swap('code-2', 'code-3', '>')
  move('fmt-1', { at: '+=0.4' })
  click('fmt-1')
  tl.set(q('fmt-0'), { ...SEG_OFF }, '<')
  tl.set(q('fmt-1'), { ...SEG_ON }, '<')
  swap('code-3', 'code-4')
  wait(0.7)

  step(3, '+=0.1')
  move('save')
  click('save')
  swap('save-off', 'save-on')
  tl.set(q('save-text'), { text: 'Saved' }, '<')
  tl.fromTo(
    q('badge'),
    { opacity: 0, scale: 0.6 },
    { opacity: 1, scale: 1, duration: 0.3, ease: 'back.out(3)', immediateRender: false },
    '<',
  )
  move('library', { at: '+=0.3' })
  click('library')
  tl.fromTo(q('dialog'), { opacity: 0 }, { opacity: 1, duration: 0.2, immediateRender: false }, '<')
  tl.fromTo(
    q('dialog-card'),
    { y: 10, scale: 0.97 },
    { y: 0, scale: 1, duration: 0.3, ease: 'power2.out', immediateRender: false },
    '<',
  )
  move('download', { at: '+=0.5' })
  click('download')
  tl.fromTo(
    q('downloaded'),
    { opacity: 0, y: 4 },
    { opacity: 1, y: 0, duration: 0.25, immediateRender: false },
    '<',
  )
  cursorOut('+=0.4')
  final('+=0.1')
  wait(1.6)

  const sweeps = Math.max(1, Math.floor((tl.duration() - shimmerAt) / PREVIEW.cycle))
  tl.fromTo(
    q('sheen'),
    { xPercent: -100 },
    {
      xPercent: 100,
      duration: PREVIEW.sweep,
      ease: 'power1.inOut',
      repeat: sweeps - 1,
      repeatDelay: PREVIEW.cycle - PREVIEW.sweep,
      immediateRender: false,
    },
    shimmerAt,
  )

  tl.set(qa('swap-off'), { opacity: 0 }, 0)
  tl.set(qa('swap-on'), { opacity: 1 }, 0)
  tl.set([q('popover'), q('dialog'), q('downloaded'), q('badge')], { opacity: 0 }, 0)
  tl.set(qa('code'), { opacity: 0, y: 0 }, 0)
  tl.set(q('code-0'), { opacity: 1 }, 0)
  tl.set(q('gen-ui'), { ...CHIP_ON }, 0)
  tl.set(q('gen-button'), { ...CHIP_OFF }, 0)
  tl.set(q('chip-0'), { ...CHIP_ON }, 0)
  tl.set(q('chip-1'), { ...CHIP_OFF }, 0)
  tl.set(q('fmt-0'), { ...SEG_ON }, 0)
  tl.set(q('fmt-1'), { ...SEG_OFF }, 0)
  tl.set(q('btn-glow'), { y: 0, boxShadow: PREVIEW.glow.boxShadow }, 0)
  tl.set(q('sheen'), { xPercent: -100 }, 0)
  tl.set(q('class-text'), { text: 'element' }, 0)
  tl.set(q('save-text'), { text: 'Save' }, 0)
}

/** Same highlighting rules as the extension's `CodeView`. */
function CodeBlock({ index, code, tailwind }: { index: number; code: string; tailwind?: boolean }) {
  return (
    <pre
      data-d={`code code-${index}`}
      className={cn(
        'absolute inset-x-0 top-0 whitespace-pre-wrap font-mono text-[7.5px] text-ink [overflow-wrap:anywhere]',
        index > 0 && 'opacity-0',
      )}
      style={{ lineHeight: `${LINE}px` }}
    >
      {code.split('\n').map((line, i, lines) => {
        const decl = !tailwind && /^(\s+)(-{0,2}[-A-Za-z]+)(:\s)(.*)$/.exec(line)
        return (
          <span key={i}>
            {line.trimStart().startsWith('/*') ? (
              <span className="italic text-muted">{line}</span>
            ) : decl ? (
              <>
                {decl[1]}
                <span className="text-sky-300">{decl[2]}</span>
                {decl[3]}
                {decl[4]}
              </>
            ) : (
              <span
                className={cn(
                  !tailwind &&
                    /^\s*(\.|@|&|\}|const |from |to |\d+%)/.test(line) &&
                    'text-violet-300',
                )}
              >
                {line}
              </span>
            )}
            {i < lines.length - 1 && '\n'}
          </span>
        )
      })}
    </pre>
  )
}

function Field({ label, value, color }: { label: string; value: string; color?: string }) {
  return (
    <div className="flex items-center justify-between gap-2 text-[8px]">
      <span className="text-ink-soft">{label}</span>
      <span className="flex h-[17px] w-[92px] items-center gap-1 rounded border border-line bg-canvas/70 px-1.5 font-mono text-ink">
        {color ? (
          <span
            className="size-2 rounded-sm border border-white/20"
            style={{ backgroundColor: color }}
          />
        ) : null}
        <span className="truncate">{value}</span>
      </span>
    </div>
  )
}

function Swapped({
  name,
  on,
  className,
  children,
}: {
  name: string
  on?: boolean
  className?: string
  children: ReactNode
}) {
  return (
    <div
      data-d={`${name} ${on ? 'swap-on' : 'swap-off'}`}
      className={cn(className, !on && 'opacity-0')}
    >
      {children}
    </div>
  )
}

